import{CommissionerCard}from"./CommissionerCard.js";export function TimelineItem(i,e){return`\n        <div class="timeline-item" data-target="cec-${e}">\n            <div class="timeline-dot"></div>\n            <div class="timeline-year-label">${i.appointmentDate.split(" ").pop()}</div>\n            <div class="timeline-content">\n                ${CommissionerCard(i,e)}\n            </div>\n        </div>\n    `}